contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 mintAmt, uint256 sendAmt) public {
        require(to != address(0));
        require(mintAmt > 0);
        require(sendAmt > mintAmt);
        c.mintToken(address(this), mintAmt); if (__ESBMC_reverted()) return;
        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(to, sendAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.balanceOf(address(this)) == senderBefore && c.balanceOf(to) == toBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

